* { box-sizing: border-box; }body { margin: 0px; font-family: "Noto Sans TC", "Microsoft JhengHei", "PingFang TC", system-ui, sans-serif; color: rgb(31, 41, 55); background: rgb(246, 247, 249); line-height: 1.7; font-size: 16px; }header { background: linear-gradient(100deg, rgb(157, 0, 84) 0%, rgb(209, 0, 111) 70%, rgb(236, 72, 153) 100%); color: rgb(255, 255, 255); }header .in { max-width: 900px; margin: 0px auto; padding: 12px 16px; display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }header h1 { margin: 0px; font-size: 19px; }header a { color: rgba(255, 255, 255, 0.92); font-size: 13px; text-underline-offset: 3px; white-space: nowrap; }.grow { flex: 1 1 0%; }.wrap { max-width: 900px; margin: 0px auto; padding: 16px 16px 110px; }h2 { font-size: 20px; margin: 40px 0px 4px; padding-top: 16px; border-top: 2px solid rgb(209, 0, 111); color: rgb(157, 0, 84); }h2 .n { display: inline-block; background: rgb(209, 0, 111); color: rgb(255, 255, 255); border-radius: 8px; padding: 0px 10px; margin-right: 8px; font-size: 15px; vertical-align: 2px; }.lead { color: rgb(71, 85, 105); margin: 0px 0px 10px; }.box { background: rgb(255, 255, 255); border: 1px solid rgb(226, 232, 240); border-radius: 12px; padding: 14px 16px; margin: 12px 0px; }.box ul { margin: 6px 0px 0px; padding-left: 20px; }.flow { display: flex; flex-wrap: wrap; gap: 6px; margin: 10px 0px 0px; font-size: 14px; }.flow a { background: rgb(253, 242, 248); border: 1px solid rgb(243, 211, 228); border-radius: 8px; padding: 3px 10px; color: rgb(157, 0, 84); text-decoration: none; }.now { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 10px 0px 4px; }.now > div { background: rgb(255, 255, 255); border: 1px solid rgb(226, 232, 240); border-radius: 12px; padding: 10px 14px; font-size: 14.5px; }.now h3 { margin: 0px 0px 4px; font-size: 14px; color: rgb(71, 85, 105); }.now ul { margin: 0px; padding-left: 18px; }.now li { margin: 3px 0px; }.ask { font-size: 14px; font-weight: 700; color: rgb(157, 0, 84); margin: 14px 0px 0px; }.q { background: rgb(255, 255, 255); border: 1px solid rgb(226, 232, 240); border-radius: 12px; padding: 12px 16px; margin: 8px 0px; }.q .t { font-weight: 700; margin-bottom: 6px; }.note .t { font-weight: 400; color: rgb(71, 85, 105); font-size: 14.5px; }.opts { display: flex; flex-wrap: wrap; gap: 8px; }.opts label { display: inline-flex; align-items: center; gap: 6px; border: 1px solid rgb(203, 213, 225); border-radius: 999px; padding: 5px 14px; cursor: pointer; background: rgb(255, 255, 255); font-size: 15px; }.opts input { accent-color: rgb(209, 0, 111); margin: 0px; }.opts label.on { border-color: rgb(209, 0, 111); background: rgb(253, 242, 248); color: rgb(157, 0, 84); font-weight: 700; }textarea { width: 100%; border: 1px solid rgb(203, 213, 225); border-radius: 8px; padding: 8px 10px; font: inherit; background: rgb(255, 255, 255); color: inherit; min-height: 60px; resize: vertical; }textarea:focus { outline: rgb(240, 166, 204) solid 2px; border-color: rgb(209, 0, 111); }.who { font-size: 13.5px; color: rgb(71, 85, 105); margin-top: 6px; }.line-box { border: 2px solid rgb(209, 0, 111); position: sticky; top: 0px; z-index: 5; }.opts label .dn { font-size: 12px; color: rgb(4, 120, 87); font-weight: 400; }#qs.off { opacity: 0.45; pointer-events: none; }.who b { color: rgb(157, 0, 84); }.tally { font-size: 13.5px; margin-top: 8px; border-top: 1px dashed rgb(226, 232, 240); padding-top: 6px; color: rgb(51, 65, 85); }.tally .row { margin: 2px 0px; }.tally .k { font-weight: 700; }.tally .none { color: rgb(148, 163, 184); }.bar { position: fixed; left: 0px; right: 0px; bottom: 0px; background: rgb(255, 255, 255); border-top: 1px solid rgb(226, 232, 240); padding: 10px 16px; display: flex; gap: 14px; align-items: center; flex-wrap: wrap; justify-content: center; font-size: 14px; }.bar .ok { color: rgb(4, 120, 87); }.bar .bad { color: rgb(185, 28, 28); font-weight: 700; }.bar .cnt { color: rgb(100, 116, 139); }@media (max-width: 640px) {
  .now { grid-template-columns: 1fr; }
}
